package selfcheck
import("testing";"task143-batchreactor/internal/forecast";"task143-batchreactor/internal/model";"task143-batchreactor/internal/report")
func TestBug10_LateStartProducesConsistentScheduleWarning(t *testing.T){r:=exothermicRecipe();f:=forecast.Build(forecast.Input{Batch:model.Batch{ID:"b",Status:model.BatchCharging,PlannedStart:10,StartedAt:20},Recipe:r,Reactor:safeReactor(),Result:&model.SafetyResult{Verdict:model.VerdictSafe,PeakTemp:400,Conversion:.95,TMRSeconds:999999},Now:20});if f.ScheduleSlip!=10||f.Risk!=model.RiskWatch{t.Fatalf("late forecast=%+v",f)};s,e:=report.Span([]report.TimelineWindow{{Start:20,End:30},{Start:10,End:15}});if s!=10||e!=30{t.Fatalf("span=%d/%d",s,e)};a:=report.Build(report.Input{Forecasts:[]model.BatchForecast{f},Now:1});if len(a.Warnings)!=1{t.Fatalf("warnings=%v",a.Warnings)}}
